\u093f\\u0924 \\u0939\\u0948:\\n\\n### 1. \\u092a\\u094d\\u0930\\u0938\\u094d\\u0924\\u093e\\u0935\\u093f\\u0924 \\u0926\\u0943\\u0937\\u094d\\u091f\\u093f\\u0915\\u094b\\u0923 (Proposed Approach)\\n\\u0939\\u092e \\u090f\\u0915 \\u092c\\u0939\\u0941-\\u0906\\u092f\\u093e\\u092e\\u0940 (multi-faceted) \\u092a\\u094d\\u0930\\u092f\\u094b\\u0917\\u093e\\u0924\\u094d\\u092e\\u0915 \\u092a\\u094d\\u0930\\u094b\\u091f\\u094b\\u0915\\u0949\\u0932 \\u0924\\u0948\\u092f\\u093e\\u0930 \\u0915\\u0930\\u0947\\u0902\\u0917\\u0947 \\u091c\\u094b \\u0926\\u094b \\u092a\\u094d\\u0930\\u092e\\u0941\\u0916 \\u0906\\u092f\\u093e\\u092e\\u094b\\u0902 \\u0915\\u0940 \\u091c\\u093e\\u0902\\u091a \\u0915\\u0930\\u0947\\u0917\\u093e:\\n\\n1. **\\u0921\\u093f\\u0938\\u090f\\u0917\\u094d\\u0930\\u0940\\u092e\\u0947\\u0902\\u091f \\u0938\\u0947\\u091f \\u0915\\u0940 \\u092a\\u0939\\u091a\\u093e\\u0928 (Disagreement Subset Identification):**\\n   - \\u0921\\u0947\\u091f\\u093e\\u0938\\u0947\\u091f \\u0915\\u094b Docta \\u0915\\u0947 \\u0932\\u0947\\u092c\\u0932-\\u0915\\u094d\\u0932\\u0940\\u0928\\u093f\\u0902\\u0917 \\u092a\\u093e\\u0907\\u092a\\u0932\\u093e\\u0907\\u0928 \\u0938\\u0947 \\u092a\\u094d\\u0930\\u094b\\u0938\\u0947\\u0938 \\u0915\\u0930\\u0947\\u0902\\u0917\\u0947\\u0964\\n   - \\u0909\\u0928 \\u0938\\u092d\\u0940 \\u0938\\u0948\\u0902\\u092a\\u0932\\u094d\\u0938 \\u0915\\u094b \\u0905\\u0932\\u0917 \\u0915\\u0930\\u0947\\u0902\\u0917\\u0947 \\u091c\\u0939\\u093e\\u0902 \\u0930\\u0949 \\u0932\\u0947\\u092c\\u0932 \\u0914\\u0930 Docta-\\u0938\\u091c\\u0947\\u0938\\u094d\\u091f\\u0947\\u0921 \\u0932\\u0947\\u092c\\u0932 \\u092e\\u0947\\u0902 \\u0905\\u0902\\u0924\\u0930 \\u0939\\u0948 ($y_{\\\\text{raw}} \\\\neq y_{\\\\text{docta}}$)\\u0964\\n\\n2. **\\u0926\\u094b\\u0939\\u0930\\u093e \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u0928 (Dual Credibility Validation: ChatGPT + In-House Annotators):**\\n   - **ChatGPT \\u0907\\u0935\\u0948\\u0932\\u094d\\u092f\\u0942\\u090f\\u0936\\u0928:** \\u0905\\u0938\\u0902\\u0930\\u0947\\u0916\\u093f\\u0924 (blinded) \\u0930\\u0942\\u092a \\u092e\\u0947\\u0902 \\u0938\\u0948\\u0902\\u092a\\u0932\\u094d\\u0938 \\u0915\\u094b \\u092e\\u093e\\u0928\\u0915\\u0940\\u0915\\u0943\\u0924 \\u092a\\u094d\\u0930\\u0949\\u092e\\u094d\\u092a\\u094d\\u091f (\\u0930\\u0942\\u092c\\u094d\\u0930\\u093f\\u0915-\\u0906\\u0927\\u093e\\u0930\\u093f\\u0924, \\u091f\\u0947\\u092e\\u094d\\u092a\\u0930\\u0947\\u091a\\u0930=0) \\u0915\\u0947 \\u0938\\u093e\\u0925 ChatGPT \\u0915\\u094b \\u092a\\u094d\\u0930\\u0938\\u094d\\u0924\\u0941\\u0924 \\u0915\\u0930\\u0947\\u0902\\u0917\\u0947, \\u0924\\u093e\\u0915\\u093f \\u0935\\u0939 \\u092c\\u093f\\u0928\\u093e \\u092f\\u0939 \\u091c\\u093e\\u0928\\u0947 \\u0915\\u093f \\u0915\\u094c\\u0928 \\u0938\\u093e \\u0932\\u0947\\u092c\\u0932 Docta \\u0915\\u093e \\u0939\\u0948 \\u0914\\u0930 \\u0915\\u094c\\u0928 \\u0938\\u093e \\u0930\\u0949, \\u0928\\u093f\\u0937\\u094d\\u092a\\u0915\\u094d\\u0937 \\u0928\\u093f\\u0930\\u094d\\u0923\\u092f \\u0926\\u0947 \\u0938\\u0915\\u0947\\u0964\\n   - **\\u0907\\u0928-\\u0939\\u093e\\u0909\\u0938 \\u0939\\u094d\\u092f\\u0942\\u092e\\u0928 \\u090f\\u0928\\u094b\\u091f\\u0947\\u0936\\u0928:** \\u092a\\u094d\\u0930\\u0936\\u093f\\u0915\\u094d\\u0937\\u093f\\u0924 \\u090f\\u0928\\u094b\\u091f\\u0947\\u091f\\u0930\\u094d\\u0938 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0938\\u092e\\u093e\\u0928 \\u0921\\u093f\\u0938\\u090f\\u0917\\u094d\\u0930\\u0940\\u092e\\u0947\\u0902\\u091f \\u0938\\u0948\\u0902\\u092a\\u0932\\u094d\\u0938 \\u0915\\u093e \\u0905\\u0902\\u0927\\u093e\\u0927\\u0941\\u0902\\u0927 (blinded) \\u092a\\u0941\\u0928\\u0930\\u094d\\u092e\\u0942\\u0932\\u094d\\u092f\\u093e\\u0902\\u0915\\u0928\\u0964 \\n   - **\\u090f\\u0917\\u094d\\u0930\\u0940\\u092e\\u0947\\u0902\\u091f \\u092e\\u0947\\u091f\\u094d\\u0930\\u093f\\u0915\\u094d\\u0938:** ChatGPT \\u0914\\u0930 \\u0939\\u094d\\u092f\\u0942\\u092e\\u0928 \\u091c\\u091c\\u092e\\u0947\\u0902\\u09