\n   - \\u092c\\u0942\\u091f\\u0938\\u094d\\u091f\\u094d\\u0930\\u0948\\u092a \\u0914\\u0930 \\u0938\\u093e\\u0902\\u0916\\u094d\\u092f\\u093f\\u0915\\u0940\\u092f \\u0938\\u093e\\u0930\\u094d\\u0925\\u0915\\u0924\\u093e \\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923 (Paired t-test, Wilcoxon signed-rank test)\\u0964\\n\\n4. **\\u0915\\u094b\\u0930\\u093f\\u0932\\u0947\\u0936\\u0928 \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923 (Credibility to Performance Link):**\\n   - \\u092f\\u0939 \\u0935\\u093f\\u0936\\u094d\\u0932\\u0947\\u0937\\u0923 \\u0915\\u0930\\u0928\\u093e \\u0915\\u093f \\u0915\\u094d\\u092f\\u093e \\u092e\\u093e\\u0928\\u0935\\u0940\\u092f \\u0914\\u0930 LLM \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u0928 \\u092e\\u0947\\u0902 Docta \\u0915\\u0940 \\u0909\\u091a\\u094d\\u091a \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u092c\\u093f\\u0932\\u093f\\u091f\\u0940 \\u0938\\u0940\\u0927\\u0947 \\u0924\\u094c\\u0930 \\u092a\\u0930 \\u092e\\u0949\\u0921\\u0932 \\u0915\\u0947 \\u092a\\u094d\\u0930\\u0926\\u0930\\u094d\\u0936\\u0928 \\u092e\\u0947\\u0902 \\u0938\\u0941\\u0927\\u093e\\u0930 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u0926\\u0943\\u0922\\u093c\\u0924\\u093e \\u0938\\u0947 \\u0938\\u0939\\u0938\\u0902\\u092c\\u0926\\u094d\\u0927 (correlated) \\u0939\\u0948 \\u092f\\u093e \\u0928\\u0939\\u0940\\u0902\\u0964\\n\\n\\u0915\\u0943\\u092a\\u092f\\u093e \\u0907\\u0938 \\u0926\\u0943\\u0937\\u094d\\u091f\\u093f\\u0915\\u094b\\u0923 \\u0915\\u0940 \\u0938\\u092e\\u0940\\u0915\\u094d\\u0937\\u093e \\u0915\\u0930\\u0947\\u0902\\u0964 \\u0906\\u092a\\u0915\\u0947 \\u0905\\u0928\\u0941\\u092e\\u094b\\u0926\\u0928 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u093e\\u0925\\u092e\\u093f\\u0915\\u0924\\u093e\\u0913\\u0902 \\u0915\\u0947 \\u0906\\u0927\\u093e\\u0930 \\u092a\\u0930 \\u0939\\u092e \\u0907\\u0938\\u0915\\u093e \\u0935\\u093f\\u0938\\u094d\\u0924\\u0943\\u0924 \\u090f\\u0915\\u094d\\u0938\\u092a\\u0947\\u0930\\u093f\\u092e\\u0947\\u0902\\u091f\\u0