\\u093e \\u0928\\u093f\\u0937\\u094d\\u0915\\u0930\\u094d\\u0937\\u0923:**\\n   $$S_{\\\\text{disagree}} = \\\\{(x_i, y_i^{\\\\text{raw}}, y_i^{\\\\text{docta}}) \\\\mid y_i^{\\\\text{raw}} \\\\ne y_i^{\\\\text{docta}}, \\\\forall i \\\\in D_{\\\\text{train}}\\\\}$$\\n   \\u092f\\u0926\\u093f $S_{\\\\text{disagree}}$ \\u0915\\u093e \\u0906\\u0915\\u093e\\u0930 \\u0905\\u0924\\u094d\\u092f\\u0927\\u093f\\u0915 \\u092c\\u0921\\u093c\\u093e \\u0939\\u094b, \\u0924\\u094b \\u0928\\u094d\\u092f\\u0942\\u0928\\u0924\\u092e 95% \\u0915\\u0949\\u0928\\u094d\\u092b\\u093f\\u0921\\u0947\\u0902\\u0938 \\u0932\\u0947\\u0935\\u0932 \\u0914\\u0930 2.5% \\u092e\\u093e\\u0930\\u094d\\u091c\\u093f\\u0928 \\u0911\\u092b \\u090f\\u0930\\u0930 \\u0915\\u0947 \\u0938\\u093e\\u0925 \\u090f\\u0915 \\u0938\\u094d\\u0924\\u0930\\u093f\\u0924 \\u092f\\u093e\\u0926\\u0943\\u091a\\u094d\\u091b\\u093f\\u0915 \\u0928\\u092e\\u0942\\u0928\\u093e (stratified random sample) $S_{\\\\text{eval}} \\\\subseteq S_{\\\\text{disagree}}$ ($N \\\\ge 1,000$) \\u0928\\u093f\\u0915\\u093e\\u0932\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\\n\\n---\\n\\n## 4. \\u0926\\u094b\\u0939\\u0930\\u093e \\u0915\\u094d\\u0930\\u0947\\u0921\\u093f\\u092c\\u093f\\u0932\\u093f\\u091f\\u0940 \\u0938\\u0924\\u094d\\u092f\\u093e\\u092a\\u0928 \\u092a\\u094d\\u0930\\u094b\\u091f\\u094b\\u0915\\u0949\\u0932 (Dual Credibility Validation Protocol)\\n\\n### 4.1 \\u092c\\u094d\\u0932\\u093e\\u0907\\u0902\\u0921\\u093f\\u0902\\u0917 \\u090f\\u0935\\u0902 \\u0915\\u093e\\u0909\\u0902\\u091f\\u0930\\u092c\\u0948\\u0932\\u0947\\u0902\\u0938\\u093f\\u0902\\u0917 (Blinding & Counterbalancing)\\n- \\u092e\\u0942\\u0932\\u094d\\u092f\\u093e\\u0902\\u0915\\u0928\\u0915\\u0930\\u094d\\u0924\\u093e\\u0913\\u0902 (\\u092e\\u093e\\u0928\\u0935 \\u0914\\u0930 LLM \\u0926\\u094b\\u0928\\u094b\\u0902) \\u0915\\u094b \\u092f\\u0939 \\u0928\\u0939\\u0940\\u0902 \\u092c\\u0924\\u093e\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e \\u0915\\u09